WITH flattened_attrs AS (SELECT id, tier_limits, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, CASE WHEN lowest_price >= 34 THEN 'HIGH' ELSE 'LOW' END AS lowest_price_tier, PERCENTILE_APPROX(lowest_price, 0.95) AS lowest_price_p95, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt FROM flattened_attrs GROUP BY GROUPING SETS ((CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN lowest_price >= 34 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END)) ORDER BY lowest_price_p95 DESC NULLS FIRST;
